package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API53 Task contracts; repeated trigger events retain occurrence order.
func TestRunTaskStatusRollupContracts(t *testing.T) {
	t.Run("lifecycle", func(t *testing.T) {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskState53.cls"), "@IsTest private class GladeTaskState53 {\nprivate static String status(Boolean closed){List<TaskStatus> rows=[SELECT MasterLabel FROM TaskStatus WHERE IsClosed=:closed];System.assert(!rows.isEmpty(),'required TaskStatus population');return rows[0].MasterLabel;}\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\nprivate static void normalizeTriggerRows(Object payload){Map<String,Object> root=(Map<String,Object>)payload;for(Object item:(List<Object>)root.get('rows')){Map<String,Object> row=(Map<String,Object>)item;if(!row.containsKey('triggerRows'))continue;Map<String,Object> keyed=new Map<String,Object>();Map<String,Integer> occurrences=new Map<String,Integer>();for(Object event:(List<Object>)row.get('triggerRows')){Map<String,Object> e=(Map<String,Object>)event;String groupKey=(String)e.get('phase')+':'+(String)e.get('subject');Integer ordinal=occurrences.containsKey(groupKey)?occurrences.get(groupKey):0;occurrences.put(groupKey,ordinal+1);keyed.put(groupKey+':'+ordinal,event);}System.assertEquals(((List<Object>)row.get('triggerRows')).size(),keyed.size(),'every trigger event retained');row.put('triggerRows',keyed);}}\nprivate static void finish(String method,List<Object> rows){String text=JSON.serialize(new Map<String,Object>{'method'=>method,'rows'=>rows,'done'=>true});System.assert(text.length()<2900,method+': observation size');Map<String,String> expectedByMethod=new Map<String,String>{'insertThenSwap'=>'{\"done\":true,\"rows\":[{\"count\":2,\"stored\":{\"closed\":true,\"open\":false},\"caller\":{\"closed\":false,\"open\":false},\"phase\":\"insert\"},{\"count\":2,\"stored\":{\"closed\":false,\"open\":true},\"caller\":{\"open\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.IsClosed\",\"type\":\"System.SObjectException\"},\"closed\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Task.IsClosed\",\"type\":\"System.SObjectException\"}},\"phase\":\"swap\"},{\"triggerRows\":[{\"oldClosed\":null,\"newClosed\":false,\"subject\":\"open\",\"phase\":\"beforeInsert\"},{\"oldClosed\":null,\"newClosed\":false,\"subject\":\"closed\",\"phase\":\"beforeInsert\"},{\"oldClosed\":null,\"newClosed\":false,\"subject\":\"open\",\"phase\":\"afterInsert\"},{\"oldClosed\":null,\"newClosed\":true,\"subject\":\"closed\",\"phase\":\"afterInsert\"},{\"oldClosed\":false,\"newClosed\":false,\"subject\":\"open\",\"phase\":\"beforeUpdate\"},{\"oldClosed\":true,\"newClosed\":true,\"subject\":\"closed\",\"phase\":\"beforeUpdate\"},{\"oldClosed\":false,\"newClosed\":true,\"subject\":\"open\",\"phase\":\"afterUpdate\"},{\"oldClosed\":true,\"newClosed\":false,\"subject\":\"closed\",\"phase\":\"afterUpdate\"}]}],\"method\":\"insertThenSwap\"}','sparseCloseThenReopen'=>'{\"done\":true,\"rows\":[{\"count\":1,\"stored\":{\"sparse\":true},\"caller\":{\"sparse\":false},\"phase\":\"closed\"},{\"count\":1,\"stored\":{\"sparse\":false},\"caller\":{\"sparse\":false},\"phase\":\"reopened\"},{\"triggerRows\":[{\"oldClosed\":null,\"newClosed\":false,\"subject\":\"sparse\",\"phase\":\"beforeInsert\"},{\"oldClosed\":null,\"newClosed\":false,\"subject\":\"sparse\",\"phase\":\"afterInsert\"},{\"oldClosed\":false,\"newClosed\":false,\"subject\":\"sparse\",\"phase\":\"beforeUpdate\"},{\"oldClosed\":false,\"newClosed\":true,\"subject\":\"sparse\",\"phase\":\"afterUpdate\"},{\"oldClosed\":true,\"newClosed\":true,\"subject\":\"sparse\",\"phase\":\"beforeUpdate\"},{\"oldClosed\":true,\"newClosed\":false,\"subject\":\"sparse\",\"phase\":\"afterUpdate\"}]}],\"method\":\"sparseCloseThenReopen\"}'};System.assert(expectedByMethod.containsKey(method),method+': expected case');Object expected=JSON.deserializeUntyped(expectedByMethod.get(method));Object actual=JSON.deserializeUntyped(text);normalizeTriggerRows(expected);normalizeTriggerRows(actual);assertObserved(expected,actual,method);}\nprivate static void snapshot(List<Object> rows,String phase,List<Task> caller){Map<String,Object> callerState=new Map<String,Object>();Map<String,Object> stored=new Map<String,Object>();Set<Id> ids=new Set<Id>();for(Task t:caller){try{callerState.put(t.Subject,t.IsClosed);}catch(Exception e){callerState.put(t.Subject,new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()});}ids.add(t.Id);}for(Task t:[SELECT Id,Subject,IsClosed FROM Task WHERE Id IN :ids])stored.put(t.Subject,t.IsClosed);rows.add(new Map<String,Object>{'phase'=>phase,'caller'=>callerState,'stored'=>stored,'count'=>stored.size()});}\n@IsTest static void insertThenSwap(){\nList<Object> rows=new List<Object>();String open=status(false),closed=status(true);List<Task> tasks=new List<Task>{new Task(Subject='open',Status=open),new Task(Subject='closed',Status=closed)};\nGladeTaskStateCapture53.enabled=true;insert tasks;snapshot(rows,'insert',tasks);\nList<Task> selected=[SELECT Id,Subject,Status FROM Task WHERE Id IN :tasks ORDER BY Subject];for(Task t:selected)t.Status=t.Subject=='open'?closed:open;\nTest.startTest();update selected;Test.stopTest();snapshot(rows,'swap',selected);rows.add(new Map<String,Object>{'triggerRows'=>GladeTaskStateCapture53.rows});finish('insertThenSwap',rows);\n}\n@IsTest static void sparseCloseThenReopen(){\nList<Object> rows=new List<Object>();String open=status(false),closed=status(true);Task task=new Task(Subject='sparse',Status=open);GladeTaskStateCapture53.enabled=true;insert task;\nTask patch=new Task(Id=task.Id,Status=closed);update patch;snapshot(rows,'closed',new List<Task>{task});\nupdate new Task(Id=task.Id,Status=open);snapshot(rows,'reopened',new List<Task>{task});rows.add(new Map<String,Object>{'triggerRows'=>GladeTaskStateCapture53.rows});finish('sparseCloseThenReopen',rows);\n}\n}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskState53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskStateCapture53.cls"), "public class GladeTaskStateCapture53 {\n public static Boolean enabled=false;\n public static List<Object> rows=new List<Object>();\n public static void capture(String phase,List<Task> current,Map<Id,Task> prior){if(!enabled)return;for(Task item:current){rows.add(new Map<String,Object>{'phase'=>phase,'subject'=>item.Subject,'newClosed'=>item.IsClosed,'oldClosed'=>prior==null?null:prior.get(item.Id).IsClosed});}}\n}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskStateCapture53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeTaskStateTrigger53.trigger"), "trigger GladeTaskStateTrigger53 on Task(before insert,after insert,before update,after update){GladeTaskStateCapture53.capture((Trigger.isBefore?'before':'after')+(Trigger.isInsert?'Insert':'Update'),Trigger.new,Trigger.isInsert?null:Trigger.oldMap);}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/triggers/GladeTaskStateTrigger53.trigger-meta.xml"), "<ApexTrigger xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexTrigger>\n")
		writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\n  \"sourceApiVersion\": \"53.0\",\n  \"packageDirectories\": [\n    {\n      \"path\": \"force-app\",\n      \"default\": true\n    }\n  ]\n}\n")
		run := Run(loadTestIndex(t, root), Options{})
		if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
			data, _ := json.Marshal(run)
			t.Fatalf("exact Task status/rollup contracts failed: %s", data)
		}
	})
	t.Run("rollup", func(t *testing.T) {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskRollup53.cls"), "@IsTest private class GladeTaskRollup53 {\nprivate static String status(Boolean closed){List<TaskStatus> rows=[SELECT MasterLabel FROM TaskStatus WHERE IsClosed=:closed];System.assert(!rows.isEmpty(),'required TaskStatus population');return rows[0].MasterLabel;}\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\nprivate static void normalizeTriggerRows(Object payload){Map<String,Object> root=(Map<String,Object>)payload;for(Object item:(List<Object>)root.get('rows')){Map<String,Object> row=(Map<String,Object>)item;if(!row.containsKey('triggerRows'))continue;Map<String,Object> keyed=new Map<String,Object>();for(Object event:(List<Object>)row.get('triggerRows')){Map<String,Object> e=(Map<String,Object>)event;String key=(String)e.get('phase')+':'+(String)e.get('subject');System.assert(!keyed.containsKey(key),'exact trigger event population '+key);keyed.put(key,event);}row.put('triggerRows',keyed);}}\nprivate static void finish(String method,List<Object> rows){String text=JSON.serialize(new Map<String,Object>{'method'=>method,'rows'=>rows,'done'=>true});System.assert(text.length()<2900,method+': observation size');Map<String,String> expectedByMethod=new Map<String,String>{'updateAndRollup'=>'{\"done\":true,\"rows\":[{\"closedTotal\":2,\"total\":3,\"groups\":{\"all:subtotal\":{\"parent\":null,\"count\":3,\"closed\":null},\"B:subtotal\":{\"parent\":\"B\",\"count\":1,\"closed\":null},\"B:closed\":{\"parent\":\"B\",\"count\":1,\"closed\":true},\"A:subtotal\":{\"parent\":\"A\",\"count\":2,\"closed\":null},\"A:closed\":{\"parent\":\"A\",\"count\":1,\"closed\":true},\"A:open\":{\"parent\":\"A\",\"count\":1,\"closed\":false}},\"phase\":\"initial\"},{\"closedTotal\":3,\"total\":3,\"groups\":{\"all:subtotal\":{\"parent\":null,\"count\":3,\"closed\":null},\"B:subtotal\":{\"parent\":\"B\",\"count\":1,\"closed\":null},\"B:closed\":{\"parent\":\"B\",\"count\":1,\"closed\":true},\"A:subtotal\":{\"parent\":\"A\",\"count\":2,\"closed\":null},\"A:closed\":{\"parent\":\"A\",\"count\":2,\"closed\":true}},\"phase\":\"allClosed\"}],\"method\":\"updateAndRollup\"}','deleteAndRollup'=>'{\"done\":true,\"rows\":[{\"closedTotal\":2,\"total\":3,\"groups\":{\"all:subtotal\":{\"parent\":null,\"count\":3,\"closed\":null},\"B:subtotal\":{\"parent\":\"B\",\"count\":1,\"closed\":null},\"B:closed\":{\"parent\":\"B\",\"count\":1,\"closed\":true},\"A:subtotal\":{\"parent\":\"A\",\"count\":2,\"closed\":null},\"A:closed\":{\"parent\":\"A\",\"count\":1,\"closed\":true},\"A:open\":{\"parent\":\"A\",\"count\":1,\"closed\":false}},\"phase\":\"initial\"},{\"closedTotal\":1,\"total\":2,\"groups\":{\"all:subtotal\":{\"parent\":null,\"count\":2,\"closed\":null},\"B:subtotal\":{\"parent\":\"B\",\"count\":1,\"closed\":null},\"B:closed\":{\"parent\":\"B\",\"count\":1,\"closed\":true},\"A:subtotal\":{\"parent\":\"A\",\"count\":1,\"closed\":null},\"A:open\":{\"parent\":\"A\",\"count\":1,\"closed\":false}},\"phase\":\"deletedClosed\"}],\"method\":\"deleteAndRollup\"}'};System.assert(expectedByMethod.containsKey(method),method+': expected case');Object expected=JSON.deserializeUntyped(expectedByMethod.get(method));Object actual=JSON.deserializeUntyped(text);normalizeTriggerRows(expected);normalizeTriggerRows(actual);assertObserved(expected,actual,method);}\nprivate static List<Task> setup(){List<GladeTaskRollup__c> parents=new List<GladeTaskRollup__c>{new GladeTaskRollup__c(Name='A'),new GladeTaskRollup__c(Name='B')};insert parents;String open=status(false),closed=status(true);List<Task> tasks=new List<Task>{new Task(Subject='Aopen',Status=open,GladeTaskRollup__c=parents[0].Id),new Task(Subject='Aclosed',Status=closed,GladeTaskRollup__c=parents[0].Id),new Task(Subject='Bclosed',Status=closed,GladeTaskRollup__c=parents[1].Id)};insert tasks;return tasks;}\nprivate static void snapshot(List<Object> rows,String phase){Map<Id,String> labels=new Map<Id,String>();for(GladeTaskRollup__c p:[SELECT Id,Name FROM GladeTaskRollup__c])labels.put(p.Id,p.Name);Set<Id> ids=labels.keySet();Map<String,Object> groups=new Map<String,Object>();for(AggregateResult r:[SELECT GladeTaskRollup__c,IsClosed,COUNT(Id) cnt FROM Task WHERE GladeTaskRollup__c IN :ids GROUP BY ROLLUP(GladeTaskRollup__c,IsClosed)]){Id parent=(Id)r.get('GladeTaskRollup__c');Boolean closed=(Boolean)r.get('IsClosed');String key=(parent==null?'all':labels.get(parent))+':'+(closed==null?'subtotal':closed?'closed':'open');System.assert(!groups.containsKey(key),phase+': unique normalized group '+key);groups.put(key,new Map<String,Object>{'closed'=>closed,'count'=>(Decimal)r.get('cnt'),'parent'=>parent==null?null:labels.get(parent)});}Integer total=[SELECT COUNT() FROM Task WHERE GladeTaskRollup__c IN :ids];Integer closedTotal=[SELECT COUNT() FROM Task WHERE GladeTaskRollup__c IN :ids AND IsClosed=true];rows.add(new Map<String,Object>{'phase'=>phase,'groups'=>groups,'total'=>total,'closedTotal'=>closedTotal});}\n@IsTest static void updateAndRollup(){List<Object> rows=new List<Object>();List<Task> tasks=setup();snapshot(rows,'initial');String closed=status(true);List<Task> selected=[SELECT Id,Status FROM Task WHERE Id IN :tasks];for(Task t:selected)t.Status=closed;Test.startTest();update selected;Test.stopTest();snapshot(rows,'allClosed');finish('updateAndRollup',rows);}\n@IsTest static void deleteAndRollup(){List<Object> rows=new List<Object>();List<Task> tasks=setup();snapshot(rows,'initial');Test.startTest();delete tasks[1];Test.stopTest();snapshot(rows,'deletedClosed');finish('deleteAndRollup',rows);}\n}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTaskRollup53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeTaskRollup__c/GladeTaskRollup__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Glade Task Rollup</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>Glade Task Rollups</pluralLabel><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/objects/Activity/fields/GladeTaskRollup__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>GladeTaskRollup__c</fullName><deleteConstraint>SetNull</deleteConstraint><label>Glade Task Rollup</label><referenceTo>GladeTaskRollup__c</referenceTo><relationshipLabel>Tasks</relationshipLabel><relationshipName>GladeTasks</relationshipName><required>false</required><type>Lookup</type></CustomField>\n")
		writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\n  \"sourceApiVersion\": \"53.0\",\n  \"packageDirectories\": [\n    {\n      \"path\": \"force-app\",\n      \"default\": true\n    }\n  ]\n}\n")
		run := Run(loadTestIndex(t, root), Options{})
		if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
			data, _ := json.Marshal(run)
			t.Fatalf("exact Task status/rollup contracts failed: %s", data)
		}
	})
}
